#!/usr/bin/env node
// hs86e-wallet-create-release.mjs
// HS86E release script - Dedicated Wallet + Create-Event + floating curved nav + gold #D4AF37.
// Pure ASCII; file payloads are base64 (byte-exact). Idempotent - safe to re-run.
// Works from the repo root (hs86e-new-build) or from inside hs86e-tickets:
//   node hs86e-wallet-create-release.mjs [path-to-repo-root]
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, mkdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";

const startDir = resolve(process.argv[2] || ".");
let APP = null;
for (const candidate of [startDir, join(startDir, "hs86e-tickets")]) {
  if (existsSync(join(candidate, "package.json"))) { APP = candidate; break; }
}
if (!APP) {
  console.log(`[FAILED] Cannot locate hs86e-tickets app root at '${startDir}' or '${join(startDir, "hs86e-tickets")}'.`);
  process.exit(1);
}
console.log("App root:", APP);

function writeB64(rel, b64) {
  const target = join(APP, rel);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, Buffer.from(b64, "base64"));
  console.log("[write]", rel);
}

// ---------- new & rewritten files (base64, byte-exact) ----------

// file: src/components/wallet/WalletModals.tsx
writeB64('src/components/wallet/WalletModals.tsx', '');

// file: src/components/wallet/WalletHistory.tsx
writeB64('src/components/wallet/WalletHistory.tsx', '');

// file: src/components/wallet/WalletScreen.tsx
writeB64('src/components/wallet/WalletScreen.tsx', '');

// file: src/components/wallet/WalletPanel.tsx
writeB64('src/components/wallet/WalletPanel.tsx', '');

// file: src/app/wallet/page.tsx
writeB64('src/app/wallet/page.tsx', '');

// file: src/app/api/wallet/transactions/route.ts
writeB64('src/app/api/wallet/transactions/route.ts', '');

// file: src/app/api/wallet/deposit/route.ts
writeB64('src/app/api/wallet/deposit/route.ts', '');

// file: src/lib/wallet/store.ts
writeB64('src/lib/wallet/store.ts', '');

// file: src/lib/wallet/idempotency.ts
writeB64('src/lib/wallet/idempotency.ts', '');

// file: src/lib/env.ts
writeB64('src/lib/env.ts', '');

// file: src/components/layout/BottomNav.tsx
writeB64('src/components/layout/BottomNav.tsx', '');

// file: src/components/layout/AppHeader.tsx
writeB64('src/components/layout/AppHeader.tsx', '');

// file: tailwind.config.ts
writeB64('tailwind.config.ts', '');

// file: src/app/api/create-event/route.ts
writeB64('src/app/api/create-event/route.ts', '');

// file: src/app/create/page.tsx
writeB64('src/app/create/page.tsx', '');

// file: src/components/create/CreateEventScreen.tsx
writeB64('src/components/create/CreateEventScreen.tsx', '');



// file: src/lib/customer-account-proxy.ts
writeB64('src/lib/customer-account-proxy.ts', '');

// file: src/app/api/account/logout/route.ts
writeB64('src/app/api/account/logout/route.ts', '');
// file: src/styles/globals.css
writeB64('src/styles/globals.css', '');

// file: supabase/migrations/20261116120000_create_events.sql
writeB64('supabase/migrations/20261116120000_create_events.sql', '');

// ---------- bulk gold standardization (idempotent) ----------
// #DFB260 family -> #D4AF37 (client-approved games accent); rgba(223,178,96,*) -> rgba(212,175,55,*)
const SRC = join(APP, "src");
const EXTENSIONS = new Set([".tsx", ".ts", ".css"]);

function* walk(dir) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) { yield* walk(full); continue; }
    if (EXTENSIONS.has(full.substring(full.lastIndexOf(".")))) yield full;
  }
}

let hexSwaps = 0, rgbaSwaps = 0, touched = 0;
for (const file of walk(SRC)) {
  const text = readFileSync(file, "utf8");
  let next = text
    .split("#DFB260").join("#D4AF37")
    .split("#Dfb260").join("#D4AF37")
    .split("#dfb260").join("#d4af37");
  next = next.replace(/rgba\(\s*223\s*,\s*178\s*,\s*96\s*,/g, () => { rgbaSwaps++; return "rgba(212, 175, 55,"; });
  if (next !== text) {
    hexSwaps += (text.match(/#(D|d)FB260/gi) || []).length;
    touched++;
    writeFileSync(file, next, "utf8");
  }
}
console.log(`[gold] files touched: ${touched} | hex swaps: ${hexSwaps} | rgba swaps: ${rgbaSwaps}`);
console.log(hexSwaps === 0 ? "[gold] 0 hex swaps - already standardized (expected)." : "[gold] gold standardized.");


console.log('');
