console.log('       WALLET_ENABLED=true, WALLET_FREEZE=true  (keep frozen until E2E passes)');
console.log('       FLW_SECRET_KEY, FLW_PUBLIC_KEY, FLW_SECRET_HASH');
console.log('       CREATE_PUBLISH_FEE_MINOR (optional; default 500000 = N5,000)');
console.log('  3. cd hs86e-tickets && npx tsc --noEmit   (must be silent)');
console.log('  4. npm run build   (expect /wallet and /create in the route table)');
console.log('  5. git add -A');
console.log('     git status');
console.log('     git restore --staged tsconfig.tsbuildinfo 2>/dev/null  (build artifact)');
console.log('  6. git commit -m "feat(wallet+create): dedicated wallet, create-event flow, floating curved nav, gold #D4AF37"');
console.log('  7. git push   (Netlify redeploys automatically)');
console.log('');
console.log('Notes:');
console.log('  - /create needs the 20261116120000 migration applied or the POST returns 502.');
console.log('  - CREATE flow stores submissions in event_submissions (pending_review);');
console.log('    a WooCommerce product is created only by admin during review - nothing goes live automatically.');
console.log('  - Header: Games / Create / Events / Wallet. Bottom nav: Games / Events / CREATE / Wallet / Account.');
console.log('  - Wallet top-up return URL is now /wallet?wallet=deposit&ref=... (redirect_url fixed in deposit route).');
console.log('  - *.bak-* backup files intentionally skipped. tsconfig.tsbuildinfo is a tracked build artifact - exclude from commits if undesired.');
console.log('');